def parse_grid(s):
    return [[int(x) for x in line.split()] for line in s.strip().split('\n')]

def find_color_groups(grid):
    """Find horizontal color groups (consecutive non-zero, non-marker colors)"""
    groups = defaultdict(list)
    visited = set()

    for r in range(len(grid)):
        for c in range(len(grid[r])):
            if grid[r][c] > 0 and grid[r][c] != 4:  # 4 is separator, != 5 is marker
                if (r, c) not in visited:
                    # Traverse horizontally
                    group = [(r, c)]
                    visited.add((r, c))
                    gc = c
                    while gc < len(grid[r]) - 1 and grid[r][gc + 1] == grid[r][c] and grid[r][gc + 1] != 0:
                        group.append((r, gc + 1))
                        visited.add((r, gc + 1))
                        gc += 1
                    groups[grid[r][c]].append(group)
    return groups

